   147→func TestDiffLines_ModifiedEstimation(t *testing.T) {
   148→	// Test diffLines with modifications (additions + removals)
   149→	// When we have both additions and removals, min(added, removed) represents modifications
   150→	checkpoint := "original1\noriginal2\noriginal3\n"
   151→	committed := "modified1\nmodified2\noriginal3\nnew line\n"
   152→
   153→	unchanged, added, removed := diffLines(checkpoint, committed)
   154→
   155→	// original3 is unchanged (1)
   156→	// original1, original2 removed (2)
   157→	// modified1, modified2, new line added (3)
   158→	if unchanged != 1 {
   159→		t.Errorf("expected 1 unchanged, got %d", unchanged)
   160→	}
   161→	if added != 3 {
   162→		t.Errorf("expected 3 added, got %d", added)
   163→	}
   164→	if removed != 2 {
   165→		t.Errorf("expected 2 removed, got %d", removed)
   166→	}
   167→
   168→	// Estimate modified lines: min(3, 2) = 2 modified
   169→	// humanModified = 2
   170→	// humanAdded = 3 - 2 = 1 (pure additions)
   171→	// humanRemoved = 2 - 2 = 0 (pure removals)
   172→	humanModified := min(added, removed)
   173→	humanAdded := added - humanModified
   174→	humanRemoved := removed - humanModified
   175→
   176→	if humanModified != 2 {
   177→		t.Errorf("expected 2 modified, got %d", humanModified)
   178→	}
   179→	if humanAdded != 1 {
   180→		t.Errorf("expected 1 pure added (after subtracting modified), got %d", humanAdded)
   181→	}
   182→	if humanRemoved != 0 {
   183→		t.Errorf("expected 0 pure removed (after subtracting modified), got %d", humanRemoved)
   184→	}
   185→}
