   187→// buildTestTree creates an object.Tree from a map of file paths to content.
   188→// This is a test helper for creating trees without a full git repository.
   189→func buildTestTree(t *testing.T, files map[string]string) *object.Tree {
   190→	t.Helper()
   191→
   192→	if len(files) == 0 {
   193→		return nil
   194→	}
   195→
   196→	// Use memory storage to build a tree
   197→	storage := memory.NewStorage()
   198→
   199→	// Create blob objects for each file
   200→	var entries []object.TreeEntry

