   200→	var entries []object.TreeEntry
   201→	for path, content := range files {
   202→		// Encode the blob
   203→		obj := storage.NewEncodedObject()
   204→		obj.SetType(plumbing.BlobObject)
   205→		writer, err := obj.Writer()
   206→		if err != nil {
   207→			t.Fatalf("failed to create blob writer: %v", err)
   208→		}
   209→		if _, err := writer.Write([]byte(content)); err != nil {
   210→			t.Fatalf("failed to write blob content: %v", err)
   211→		}
   212→		writer.Close()
   213→
   214→		// Store the blob
   215→		hash, err := storage.SetEncodedObject(obj)
   216→		if err != nil {
   217→			t.Fatalf("failed to store blob: %v", err)
   218→		}
   219→
   220→		// Create tree entry
   221→		entries = append(entries, object.TreeEntry{
   222→			Name: path,
   223→			Mode: 0o100644,
   224→			Hash: hash,
   225→		})
   226→	}
   227→
   228→	// Sort entries by name (required by git tree format)
   229→	sort.Slice(entries, func(i, j int) bool {
   230→		return entries[i].Name < entries[j].Name
   231→	})
   232→
   233→	// Create the tree
   234→	tree := &object.Tree{
   235→		Entries: entries,
   236→	}
   237→
   238→	// Encode and store the tree
   239→	obj := storage.NewEncodedObject()
   240→	obj.SetType(plumbing.TreeObject)
   241→	if err := tree.Encode(obj); err != nil {
   242→		t.Fatalf("failed to encode tree: %v", err)
   243→	}
   244→
   245→	hash, err := storage.SetEncodedObject(obj)
   246→	if err != nil {
   247→		t.Fatalf("failed to store tree: %v", err)
   248→	}
   249→
   250→	// Retrieve the tree
   251→	treeObj, err := object.GetTree(storage, hash)
   252→	if err != nil {
   253→		t.Fatalf("failed to get tree: %v", err)
   254→	}
   255→
   256→	return treeObj
   257→}
