	logCtx := logging.WithComponent(h.ctx, "checkpoint")
	shouldCondense := h.shouldCondenseWithOverlapCheck(state.Phase.IsActive(), state.LastInteractionTime)
	var parentCommitHash string
	if h.commit.NumParents() > 0 {
