   188→// buildTestTree creates an object.Tree from a map of file paths to content.
   189→// This is a test helper for creating trees without a full git repository.
   190→func buildTestTree(t *testing.T, files map[string]string) *object.Tree {
   191→	t.Helper()
   192→
   193→	if len(files) == 0 {
   194→		return nil
   195→	}
   196→
   197→	// Use memory storage to build a tree
   198→	storage := memory.NewStorage()
   199→
   200→	// Create blob objects for each file
   201→	var entries []object.TreeEntry
   202→	for path, content := range files {
   203→		// Encode the blob
   204→		obj := storage.NewEncodedObject()
   205→		obj.SetType(plumbing.BlobObject)
   206→		writer, err := obj.Writer()
   207→		if err != nil {
   208→			t.Fatalf("failed to create blob writer: %v", err)
   209→		}
   210→		if _, err := writer.Write([]byte(content)); err != nil {
   211→			t.Fatalf("failed to write blob content: %v", err)
   212→		}
   213→		writer.Close()
   214→
   215→		// Store the blob
   216→		hash, err := storage.SetEncodedObject(obj)
   217→		if err != nil {
   218→			t.Fatalf("failed to store blob: %v", err)
   219→		}
   220→
   221→		// Create tree entry
   222→		entries = append(entries, object.TreeEntry{
   223→			Name: path,
   224→			Mode: 0o100644,
   225→			Hash: hash,
   226→		})
   227→	}
   228→
   229→	// Sort entries by name (required by git tree format)
   230→	sort.Slice(entries, func(i, j int) bool {
   231→		return entries[i].Name < entries[j].Name
   232→	})
   233→
   234→	// Create the tree
   235→	tree := &object.Tree{
   236→		Entries: entries,
   237→	}
   238→
   239→	// Encode and store the tree
   240→	obj := storage.NewEncodedObject()
   241→	obj.SetType(plumbing.TreeObject)
   242→	if err := tree.Encode(obj); err != nil {
   243→		t.Fatalf("failed to encode tree: %v", err)
   244→	}
   245→
   246→	hash, err := storage.SetEncodedObject(obj)
   247→	if err != nil {
   248→		t.Fatalf("failed to store tree: %v", err)
   249→	}
   250→
   251→	// Retrieve the tree
   252→	treeObj, err := object.GetTree(storage, hash)
   253→	if err != nil {
   254→		t.Fatalf("failed to get tree: %v", err)
   255→	}
   256→
   257→	return treeObj
   258→}
